{
  "title": "The Glass Diver's Rescue",
  "gate_token": "tH3Ounp-Ssxl9HvGR-TtcQ",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara the Cartographer unfolds a torn map of the ruined city.",
      "visual_description": "A dust-choked room with broken stained glass, Mara leans over a table, her ink-stained coat catching the dim light from a single candle.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Glass Diver swims through a cracked mirror into the city.",
      "visual_description": "A large ornate mirror splinters as a figure in a clear diving helmet and a coat reflecting shards of light emerges, ripples of glass behind them.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp flickers a warning about the castle gates.",
      "visual_description": "On a stone pedestal, an oil lamp with a single glowing eye casts shadows across a narrow alley, the flame pulsing urgently.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "Mara and the Glass Diver meet at a ruined fountain.",
      "visual_description": "A cracked marble fountain with stagnant water, two figures—one with a compass, one in a diving helmet—confer under a tattered royal banner hanging from a broken arch.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The Tin Fox scampers ahead, its key-wind tail spinning.",
      "visual_description": "A small metal fox with blue glass eyes darts over rubble, its tail winding as it sniffs the air near a collapsed tower.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The Sleeping Tax Collector snores on a pile of ledgers.",
      "visual_description": "In a roofless chamber, a figure sleeps with a ledger book pillow, stamped papers stuck to their sleeves, oblivious to the dust and broken glass around them.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "The Oracle Lamp warns of a cursed tower ahead.",
      "visual_description": "The lamp's flame guttering, its eye staring at a twisted spire with dark ivy, the sky behind it bruised purple.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "Mara traces a new route around the tower on her map.",
      "visual_description": "Kneeling by a broken wall, Mara's ink-stained fingers draw a line on parchment, her brass compass gleaming, the Tin Fox watching.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The Glass Diver peers through a window into a locked room.",
      "visual_description": "A black iron door with a glowing rune, the Glass Diver's helmet pressed against a grimy window, their reflection distorting in the glass.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "The Tin Fox leads them past an armored patrol.",
      "visual_description": "In a narrow street, the small metal fox freezes, its ears twitching, as figures in full plate armor march at a distance, their steps echoing.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "The Oracle Lamp reveals a hidden passage behind a tapestry.",
      "visual_description": "A moth-eaten royal tapestry, the lamp's light pushing through it to show a dark opening, dust motes dancing.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "The Sleeping Tax Collector stirs, offering a useless stamp.",
      "visual_description": "The collector half-awake, fumbling with a stamp that leaves a faded mark on Mara's map, then immediately dozing off again.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The Glass Diver swims through a mirror to unlock the magic door.",
      "visual_description": "A mirror surface rippling, the Glass Diver's hand reaching through to turn a key on the other side, the door's runes fading.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The group enters a throne room with a shattered crown.",
      "visual_description": "A vast hall with broken columns, a fallen chandelier, and a dented crown on the floor, the Oracle Lamp casting long shadows.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The Sleeping Tax Collector wanders in, still half-asleep.",
      "visual_description": "The collector stumbling over rubble, papers trailing, blinking at the scene with utter disinterest.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The Tin Fox detects a trap on the bridge.",
      "visual_description": "A stone bridge over a dry moat, the Tin Fox sniffing at a loose flagstone, its blue eyes glowing as it detects mechanism below.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The Glass Diver leads the final escape across the bridge.",
      "visual_description": "The Glass Diver running ahead, coat billowing, helmet gleaming in moonlight, the bridge groaning as the group follows, the Tin Fox on their shoulder.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "They emerge beyond the city walls at dawn.",
      "visual_description": "The ruined skyline receding, the group standing on a hill, the first light catching the Glass Diver's helmet and the Tin Fox's metal body, Mara folding her map.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

